import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 0:
        return '0\n'

    @lru_cache(maxsize=None)
    def dp(i, j):
        if i > j:
            return 0
        if i == j:
            return 1 if a[i] > 0 else 0

        m = max(a[i:j+1])

        ans = a[i] + dp(i + 1, j)

        for k in range(i, j):
            ans = min(ans, dp(k + 1, j) + a[i])

        return ans

    return str(dp(0, n-1)) + '\n'

