    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    # Get unique x and y coordinates
    xs = sorted(set(p[0] for p in points))
    ys = sorted(set(p[1] for p in points))

    # Map original coordinates to indices
    x_map = {x: i + 1 for i, x in enumerate(xs)}
    y_map = {y: i + 1 for i, y in enumerate(ys)}

    m = len(points)
    superset = list(points)
    original_map = {p: i for i, p in enumerate(points)}

    # Add corner points for each unique x-y combination
    # Create a grid of all combinations
    for i in range(len(xs)):
        for j in range(len(ys)):
            if (xs[i], ys[j]) not in points:
                if i > 0 and j > 0:
                    superset.append((xs[i], ys[j]))

    # Add intermediate coverage points to ensure all pairs are covered
    # Join points within the same x or y group
    for x in xs:
        ys_x = [y for p in points if p[0] == x]
        for i in range(len(ys_x)):
            for j in range(i + 1, len(ys_x)):
                if (x, ys_x[i]) in original_map and (x, ys_x[j]) in original_map:
                    # These two points share x, they're covered, no need to add
                    pass

    # Ensure coverage between non-aligned points
    added = set()
    for x1 in xs:
        for x2 in xs:
            if x1 == x2:
                continue
            for y1 in ys:
                for y2 in ys:
                    # Point (x1, y2) covers rectangle between (x1,y1) and (x2,y2)
                    if (x1, y2) not in points:
                        if len(superset) > 200000:
                            break
                        superset.append((x1, y2))
                        added.add((x1, y2))
                    else:
                        added.add((x1, y2))

    # Remove duplicates
    unique_superset = list(dict.fromkeys(superset))

    # Remove excessive points
    if len(unique_superset) > 200000:
        # Keep original points and essential coverage points
        result = list(points)
        # Add some key coverage points
        for x in xs[:min(5, len(xs))]:
            for y in ys[:min(5, len(ys))]:
                if (x, y) not in points:
                    result.append((x, y))

        unique_superset = result

    output_lines = [str(len(unique_superset))]
    for x, y in unique_superset:
        output_lines.append(f"{x} {y}")

    return '\n'.join(output_lines)

