def solution(input_str):
    import sys
    sys.setrecursionlimit(1000000)

    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        clause = parts[1:]
        clauses.append(clause)

    num_nodes = 2 * m

    def to_node(lit):
        if lit > 0:
            return 2 * (lit - 1)
        else:
            return 2 * (abs(lit) - 1) + 1

    graph = [[] for _ in range(num_nodes)]
    graph_rev = [[] for _ in range(num_nodes)]

    for clause in clauses:
        nodes_in_clause = [to_node(lit) for lit in clause]
        for i in range(len(nodes_in_clause)):
            for j in range(i + 1, len(nodes_in_clause)):
                u = nodes_in_clause[i] ^ 1
                v = nodes_in_clause[j]
                graph[u].append(v)
                graph_rev[v].append(u)

    visited = [False] * num_nodes
    order = []

    def dfs1(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs1(neighbor)
        order.append(node)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    scc = [[] for _ in range(num_nodes)]
    scc_id = [-1] * num_nodes
    scc_count = 0

    def dfs2(node, scc_idx):
        scc_id[node] = scc_idx
        scc[scc_idx].append(node)
        for neighbor in graph_rev[node]:
            if scc_id[neighbor] == -1:
                dfs2(neighbor, scc_idx)

    for i in range(len(order) - 1, -1, -1):
        node = order[i]
        if scc_id[node] == -1:
            dfs2(node, scc_count)
            scc_count += 1

    for i in range(m):
        pos_node = 2 * i
        neg_node = 2 * i + 1
        if scc_id[pos_node] == scc_id[neg_node]:
            return "NO\n"

    assignment = [0] * m
    for i in range(m):
        pos_node = 2 * i
        neg_node = 2 * i + 1
        if scc_id[pos_node] < scc_id[neg_node]:
            assignment[i] = 1
        else:
            assignment[i] = 0

    result = "YES\n" + "".join(map(str, assignment))
    return result

