def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for i in range(1, n + 1):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == '1':
            events.append(1)
        else:
            events.append((2, parts[1]))

    # Count actual entries (excluding empty lines)
    actual_n = len(events)

    # Get all friends and map them to IDs
    friend_names = sorted(set(f[1] for f in events if f[0] == 2))
    name_to_id = {name: i for i, name in enumerate(friend_names)}

    # Build conflict graph: adj[i][j] = True if friends i and j appear in same block
    adj = [[False] * m for _ in range(m)]

    i = 0
    while i < actual_n:
        if events[i] == 1:
            i += 1
            continue

        # Start of a block of visit events
        friend_in_block = list()  # IDs of friends in this block
        while i < actual_n and events[i][0] == 2:
            friend_id = name_to_id[events[i][1]]
            friend_in_block.append(friend_id)
            i += 1

        # Mark conflicts between friends in the same block
        for u in friend_in_block:
            for v in friend_in_block:
                if u != v:
                    adj[u][v] = adj[v][u] = True

    # Now find Maximum Independent Set using recursive search with pruning
    # memo: dict mapping (node, mask_state) -> result

    n_friends = len(friend_names)

    # Recursive function for Maximum Independent Set
    def max_independent_set(node_idx, mask, size):
        # Find remaining nodes (0..m-1, using inverted bits)
        if node_idx == n_friends:
            return max(size, best_found)

        # Pruning: if remaining nodes can't improve best_found, skip
        remaining_nodes = node_idx
        if best_found + remaining_nodes <= size:
            return max(max_independent_set(node_idx + 1, mask, size), best_found)

        # Try not including node_idx
        result1 = max_independent_set(node_idx + 1, mask, max(size, size))

        # Try including node_idx if it doesn't conflict with current mask
        can_include = True
        for excluded in mask:
            if adj[node_idx][excluded]:
                can_include = False
                break

        if can_include:
            result2 = max_independent_set(node_idx + 1, mask | (1 << node_idx), size + 1)
            if best_found < result2:
                best_found = result2
                result1 = result2

        return result1

    best_found = 0
    best_found = max_independent_set(0, 0, 0)

    result = best_found
    best_found = 0
    best_found = max_independent_set(0, 0, 0)

    # More efficient approach: OTP (meet-in-the-middle style)
    # But for m ≤ 40, let's try memoized recursion on AT most m nodes

    memo = {}

    def solve_mis(mask):
        if mask in memo:
            return memo[mask]

        # Find first unused bit
        first_unused = -1
        for i in range(m):
            if not (mask & (1 << i)):
                first_unused = i
                break

        if first_unused == -1:
            memo[mask] = 0
            return 0

        # Option 1: Don't include first_unused
        result1 = solve_mis(mask | (1 << first_unused))

        # Option 2: Include first_unused if no conflicts
        neighbors = 0
        for other in range(first_unused + 1, m):
            if not (mask & (1 << other)) and adj[first_unused][other]:
                neighbors |= (1 << other)

        result2 = solve_mis(mask | (1 << first_unused) | neighbors)
        memo[mask] = max(result1, result2)
        return memo[mask]

    return str(solve_mis(0))

