                all_free = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        all_free = False
                        break

                if all_free:
                    # Mark all days as occupied
                    for day in range(l, r + 1):
                        occupied[day] = True
                    total += length
                    num_occupied += length

        results.append(str(total))

    return '\n'.join(results) + '\n'


