import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # result[j] = earliest time to reach j bananas, -1 if impossible
    result = [-1] * (m + 1)

    # Start with k=0 as the only reachable value
    reachable = {0}

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        t = parts[0]
        x_prime = parts[1]
        y = parts[2]
        x = x_prime / 100000.0

        new_reachable = set()

        # For each currently reachable value, try applying the operation 0 to y times
        for k in reachable:
            for a in range(y + 1):
                if a == 0:
                    new_k = k
                else:
                    new_k = k
                    for _ in range(a):
                        # Apply the operation once
                        if t == 1:
                            new_k = math.ceil(new_k + x)
                        else:  # t == 2
                            new_k = math.ceil(new_k * x)

                # Cap at m since we only care about values up to m
                if new_k > m:
                    new_k = m

                new_reachable.add(new_k)

        # The values from the previous step are still reachable (by choosing a_i=0)
        new_reachable.update(reachable)

        # Update result for positions that haven't been reached before
        for k in new_reachable:
            if 1 <= k <= m:
                if result[k] == -1:
                    result[k] = i

        # Update reachable set
        reachable = new_reachable

    # Output result[1..m]
    return ' '.join(map(str, result[1:m+1])) + '\n'

