def is_lucky(n):
    s = str(n)
    return all(c in '47' for c in s)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    n, m = map(int, lines[0].split())

    if m == 0:
        # All islands are isolated
        components = [1] * n
    else:
        adj = [[] for _ in range(n + 1)]
        idx = 1
        for line in lines[1:]:
            parts = list(map(int, line.strip().split()))
            u, v = parts[0], parts[1]
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * (n + 1)
        components = []
        for i in range(1, n + 1):
            if not visited[i]:
                stack = [i]
                visited[i] = True
                size = 0
                while stack:
                    curr = stack.pop()
                    size += 1
                    for neighbor in adj[curr]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
                components.append(size)

    # Check if we can already use one component
    for size in components:
        if is_lucky(size):
            return '0\n'

    from collections import Counter
    size_groups = Counter(components)

    # If n itself is lucky, answer is merging all components
    if is_lucky(n):
        return str(len(components) - 1) + '\n'

    # Generate lucky numbers up to n
    lucky = []
    for length in range(1, 6):  # lengths 1 to 5 (covers 10^5)
        for mask in range(1 << length):
            num = 0
            for i in range(length):
                if (mask >> i) & 1:
                    num = num * 10 + 4
                else:
                    num = num * 10 + 7
            if num <= n and num not in lucky:
                lucky.append(num)

    # DP approach: track all reachable sums with minimum components
    # Use dictionary: reachable_sums[min_components] = minimum components to reach sum
    from collections import defaultdict
    reachable = {0: 0}

    for size, count in size_groups.items():
        # For each component size, update reachable sums
        new_key_list = list(reachable.items())
        for current_sum, num_components in new_key_list:
            new_sum = current_sum + size
            if new_sum > n:
                continue
            if is_lucky(new_sum):
                return str(num_components) + '\n'
            if new_sum not in reachable or reachable[new_sum] > num_components + 1:
                reachable[new_sum] = num_components + 1
                if new_sum in lucky:
                    return str(reachable[new_sum]) + '\n'

    return '-1\n'

