import math

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return math.comb(n, r)

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())

    # If no one has a 20 euro banknote, Charlie doesn't need change
    if m == 0:
        return "1.000000"

    # If there aren't enough 10 euro banknotes (including initial k) to give change to all m people
    if n + k < m:
        return "0.000000"

    # Total arrangements of n people with 10 euros and m people with 20 euros
    total_arrangements = nCr(n + m, m)

    # Using reflection principle: count paths that dip below 0
    # Number of bad paths where we run out of change
    bad_paths = nCr(n + m, m - k - 1)

    prob = (total_arrangements - bad_paths) / total_arrangements

    return f"{prob:.10f}"

from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    adj = [[] for _ in range(n + 1)]

    for i in range(1, n):
        a, b = map(int, lines[i].split())
        adj[a].append(b)
        adj[b].append(a)

    parent = [0] * (n + 1)
    subtree_size = [0] * (n + 1)

    # DFS to build parent pointers and subtree sizes
    def compute_size(u, p):
        subtree_size[u] = 1
        for v in adj[u]:
            if v != p:
                parent[v] = u
                compute_size(v, u)
                subtree_size[u] += subtree_size[v]

    compute_size(1, 0)

    memo = {}

    def dp(u):
        # Returns a dict: size -> max_product for subtree u (when u's component has that size)
        if u in memo:
            return memo[u]

        dp = {1: 1}

        for v in adj[u]:
            if v == parent[u]:
                continue

            child_dp = dp(v)
            child_size = sum(child_dp.keys())

            new_dp = {}

            for s_u, prod_u in dp.items():
                for s_v, prod_v in child_dp.items():
                    # Option 1: Cut edge between u and v
                    key = max(s_u, s_u + s_v)
                    value = prod_u * prod_v
                    if key in new_dp:
                        new_dp[key] = max(new_dp[key], value)
                    else:
                        new_dp[key] = value

                    # Option 2: Don't cut edge, merge components
                    merged_size = s_u + s_v
                    value = max(prod_u * 1, prod_v * 1)
                    if merged_size in new_dp:
                        new_dp[merged_size] = max(new_dp[merged_size], value)
                    else:
                        new_dp[merged_size] = value

            dp = new_dp

        dp[1] = 1  # Update base case
        memo[u] = dp
        return dp

    final_dp = dp(1)
    result = max(final_dp.values())

    return str(result)

def solution(input_data):
