    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    x = list(map(int, lines[m + 1].split()))

    # Handle case where all vertices need even visits (empty path)
    if all(xi == 0 for xi in x):
        return "0\n"

    # Handle case with no edges
    if m == 0:
        if sum(x) == 1:
            for i in range(1, n + 1):
                if x[i - 1] == 1:
                    return "1\n" + str(i) + "\n"
        return "-1\n"

    result = []
    max_len = 4 * n

    def dfs(u, depth):
        if len(result) > max_len:
            return False

        result.append(u)

        # Calculate current visit counts
        cnts = [0] * (n + 1)
        for node in result:
            cnts[node] += 1

        # Check if all parities are satisfied
        ok = True
        for i in range(1, n + 1):
            if cnts[i] % 2 != x[i - 1]:
                ok = False
                break

        if ok:
            return True

        result.pop()

        # Try all adjacent vertices
        for v in adj[u]:
            result.append(v)
            if dfs(v, depth + 1):
                return True
            result.pop()

        return False

    # Try starting from each vertex
    for start in range(1, n + 1):
        if dfs(start, 1):
            break

    output = [str(len(result))] + [str(r) for r in result]
    return "\n".join(output)

from collections import defaultdict, deque
import sys

sys.setrecursionlimit(2000)

class MaxFlow:
    def __init__(self, num_nodes):
        self.n = num_nodes
        self.cap = defaultdict(lambda: defaultdict(int))
        self.graph = defaultdict(list)

    def add_edge(self, u, v, cap):
        self.graph[u].append(v)
        self.graph[v].append(u)
        self.cap[u][v] = cap
        self.cap[v][u] = 0

    def bfs(self, s, t):
        dist = {node: -1 for node in range(self.n)}
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in self.graph[u]:
                if self.cap[u][v] > 0 and dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    def dfs(self, u, t, flow, dist, ptr):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v = self.graph[u][i]
            if dist[v] == dist[u] + 1 and self.cap[u][v] > 0:
                pushed = self.dfs(v, t, min(flow, self.cap[u][v]), dist, ptr)
                if pushed > 0:
                    self.cap[u][v] -= pushed
                    self.cap[v][u] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        max_f = 0
        while True:
            dist = self.bfs(s, t)
            if dist[t] == -1:
