    """Check if constraint system is feasible using BFS with component tracking."""
    adj = defaultdict(list)
    for u, v, c in edges:
        adj[u].append((v, c))
        adj[v].append((u, c))

    visited = set()
    node_values = {}  # Maps node -> relative value

    for start in range(n):
        if start in visited or node_values.get(start) is not None:
            continue

        # BFS with component tracking
        component_visited = {start: 0}
        queue = deque([start])
        possible = True

        while queue and possible:
            u = queue.popleft()

            # Check edge constraints
            for v, c in adj[u]:
                if v not in component_visited:
                    # Assign relative value
                    component_visited[v] = component_visited[u] + 1
                    queue.append(v)

                # Check edge constraint consistency
                if u in component_visited and v in component_visited:
                    if c == 1:
                        expected = component_visited[v] + component_visited[u]
                    else:  # c = 2
                        expected = component_visited[v] + component_visited[u]

                    # For L1 minimization, we need odd cycle detection
                    if abs(expected - c) > 1e-6:
                        possible = False

        for v in component_visited:
            visited.add(v)
            node_values[v] = component_visited[v]

