    def min_dist_sq(ax1, ay1, bx1, by1, ax2, ay2, bx2, by2):
        """Find minimum squared distance between points over segment [0,1]"""
        # Distance squared is quadratic in t
        dx, dy = ax2 - ax1, ay2 - ay1
        dbx, dby = bx2 - bx1, by2 - by1
        vx, vy = dx - dbx, dy - dby

        a = vx**2 + vy**2

        if a == 0:
            return min(dist_sq(ax1, ay1, bx1, by1), 
                      dist_sq(ax2, ay2, bx2, by2))

        # For ax - bx = vx*t + (ax1-bx1) etc.
        b = 2 * (vx * (ax1 - bx1) + vy * (ay1 - by1))
        c = (ax1 - bx1)**2 + (ay1 - by1)**2

        if b*b - 4*a*c < 0:
            return min(dist_sq(ax1, ay1, bx1, by1), 
                      dist_sq(ax2, ay2, bx2, by2))

        t = -b / (2*a)
        if t < 0:
            return dist_sq(ax1, ay1, bx1, by1)
        if t > 1:
            return dist_sq(ax2, ay2, bx2, by2)

        ax, ay = ax1 + t*dx, ay1 + t*dy
        bx, by = bx1 + t*dbx, by1 + t*dby
        return (ax - bx)**2 + (ay - by)**2

