        d1_start = dist_sq(ax1, ay1, bx1, by1)
        d1_end = dist_sq(ax2, ay2, bx2, by2)
        min_d = min_dist_sq(ax1, ay1, bx1, by1, ax2, ay2, bx2, by2)

        start_in_d1 = d1_start <= d1_sq
        end_in_d1 = d1_end <= d1_sq
        mid_in_d1 = min_d <= d1_sq

        # Reset: check if entire segment is outside d2
        if not start_in_d1 and not end_in_d1 and not mid_in_d1:
            inside_d2 = True

        # If we leave d1 (end_in_1 but not mid_in_1) or enter d1
        else:
