def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "0"

    try:
        N = int(lines[0])
    except ValueError:
        return "0"

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line and len(line) > 1:
            try:
                u, v = map(int, line.split())
                adj[u].append(v)
                adj[v].append(u)
            except ValueError:
                continue

    best_potential = [0]
    all_nodes = set(range(N))

    def compute_potential(order):
        """Compute total potential sum for given order"""
        total = 0
        for i, core in enumerate(order):
            # Inactive nodes are those not yet in order[0:i]
            inactive = all_nodes - set(order[:i])

            # Find all inactive nodes reachable from core
            reachable = {core}
            if core in inactive:
                stack = [core]
                while stack:
                    node = stack.pop()
                    if node not in reachable:
                        reachable.add(node)
                        for neighbor in adj[node]:
                            if neighbor in inactive:
                                stack.append(neighbor)
            # If core is already active, reachable is just {core} but we're counting from core itself

            total += len(reachable)

        return total

    def backtrack(path, activated):
        """Try all valid orderings where each node has an activated neighbor"""
        if len(path) == N:
            potential = compute_potential(path)
            if potential > best_potential[0]:
                best_potential[0] = potential
            return

        # Try adding each unactivated node
        for node in range(N):
            if node not in activated:
                # Check if node can be activated (has an activated neighbor or is the first)
                can_activate = any(n in activated for n in adj[node])

                if can_activate:
                    activated.add(node)
                    path.append(node)
                    backtrack(path, activated)
                    path.pop()
                    activated.remove(node)

    # Try each starting node
    for start in range(N):
        activated = {start}
        path = [start]
        backtrack(path, activated)

    return str(best_potential[0])

