            u, v = map(int, lines[i].split())
            edges.append((u, v))

    # Normalize each edge so u < v for consistent comparison
    for i in range(len(edges)):
        u, v = edges[i]
        if u > v:
            edges[i] = (v, u)

    # State: 0=unassigned, 1=outside, 2=inside
    state = [0] * m
    out_edges = []  # List of edges assigned outside
    in_edges = []   # List of edges assigned inside

    def check_outside(idx):
        """Check if edge idx would conflict with other outside edges"""
        u, v = edges[idx]
        for x, y in out_edges:
            # Two chords (u,v) and (x,y) cross if endpoints alternate
            # That is: u < x < v < y or x < u < y < v
            if u < x < v < y or x < u < y < v:
                return True
        return False

    def check_inside(idx):
        """Check if edge idx would conflict with other inside edges"""
        u, v = edges[idx]
        for x, y in in_edges:
            if u < x < v < y or x < u < y < v:
                return True
        return False

    def backtrack(idx):
        if idx == m:
            return True

        u, v = edges[idx]
        can_out = not check_outside(idx)
        can_in = not check_inside(idx)

        # Try both options if both are possible
        if can_out and can_in:
            if backtrack(idx + 1):
                return True

        # Try outside placement
        if can_out:
            state[idx] = 1
            out_edges.append((u, v))
            if backtrack(idx + 1):
                return True
            out_edges.pop()
            state[idx] = 0

        # Try inside placement
        if can_in:
            state[idx] = 2
            in_edges.append((u, v))
            if backtrack(idx + 1):
                return True
            in_edges.pop()
            state[idx] = 0

        return False

    if not backtrack(0):
        return 'Impossible'

    # Convert state to output: 1 -> 'i' (inside), 
    # but wait - we need outside='o' and inside='i'
    # Actually checking the problem again:
    # 'i' = inside, 'o' = outside
    result = []
    for i in range(m):
