        'val': (left['val'] * power_mod(10, right['len'], MOD) + right['val']) % MOD
    }

def range_concat(l, r):
    """Concatenate integers from l to r, e.g., 8-11 gives 891011"""
    length = 0
    value = 0
    for i in range(l, r + 1):
        s = str(i)
        length += len(s)
        value = (value * power_mod(10, len(s), MOD) + i) % MOD
    return {'len': length, 'val': value}

def repeat_concat(n, expr_len, expr_val):
    """Concatenate expr_val, expr_len times giving a repeated expression"""
    if expr_len == 0 or n == 0:
        return {'len': 0, 'val': 0}
