    ten_pow_len = power_mod(10, expr_len, MOD)
    sum_geom = (power_mod(10, expr_len * n, MOD) - 1) * inverse_mod(ten_pow_len - 1, MOD) % MOD
    return {'len': expr_len * n, 'val': (expr_val * sum_geom) % MOD}

