    @lru_cache(maxsize=None)
    def count_perfect(m):
        if m == 0:
            return 1

        if m == 1:
            return 2

        # For even m
        if m % 2 == 0:
            return count_perfect(m - 1)

        # For odd m: we have {0}, {0,x} sets, plus subspaces
        # count is count_perfect(m-1) + 1 for the new singleton {0,m}
        # plus some additional subspaces
        return (count_perfect(m - 1) + 1 + count_perfect(m // 2)) % MOD

    result = count_perfect(k) % 1000000007
    return f"{result}\n"

